import math

def compute_activation_and_grad(z, func_name):
    if func_name == "relu":
        a = max(0.0, z)
        grad = 1.0 if z > 0.0 else 0.0
    elif func_name == "sigmoid":
        a = 1.0 / (1.0 + math.exp(-z))
        grad = a * (1.0 - a)
    return (round(a, 4), round(grad, 4))

compute_activation_and_grad(0.0, "sigmoid")

