def add_backward(upstream_grad: float) -> tuple[float, float]:
    return (upstream_grad * 1.0, upstream_grad * 1.0)

def mul_backward(upstream_grad: float, x: float, y: float) -> tuple[float, float]:
    return (upstream_grad * y, upstream_grad * x)

